// Takes README screenshots of the running ReSpec app (backend :8000, frontend :3000).
const { chromium } = require("playwright-core");
const path = require("path");

const OUT = process.argv[2];
const ONLY = process.argv[3] ? process.argv[3].split(",") : null;
const EXE = process.env.LOCALAPPDATA + "\\ms-playwright\\chromium-1248\\chrome-win64\\chrome.exe";
const BASE = "http://localhost:3000";
const REQ = "REQ-G60-US-213237";

const shots = [
  { name: "home", url: "/", wait: 4000 },
  { name: "cockpit", url: "/cockpit?scenario=G60-US", wait: 2500 },
  { name: "requirement", url: `/requirements/${REQ}?scenario=G60-US`, wait: 2500 },
  { name: "requirement-full", url: `/requirements/${REQ}?scenario=G60-US`, wait: 2500, full: true },
  { name: "audit", url: "/audit?scenario=G60-US", wait: 2500 },
  { name: "insights", url: "/insights?scenario=G60-US", wait: 2500 },
  { name: "benchmarks", url: "/benchmarks", wait: 2500 },
  { name: "portfolio", url: "/portfolio", wait: 2500 },
  { name: "evidence", url: "/evidence?scenario=G60-US", wait: 2500 },
];

(async () => {
  const browser = await chromium.launch({ executablePath: EXE });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1, colorScheme: "light" });
  for (const s of shots) {
    if (ONLY && !ONLY.includes(s.name)) continue;
    await page.goto(BASE + s.url, { waitUntil: "networkidle" });
    await page.waitForTimeout(s.wait);
    const file = path.join(OUT, s.name + ".png");
    await page.screenshot({ path: file, fullPage: !!s.full });
    console.log("saved", file);
  }
  await browser.close();
})();

