// Feature screenshots that need a click or typed input.
const { chromium } = require("playwright-core");
const path = require("path");
const OUT = process.argv[2];
const EXE = process.env.LOCALAPPDATA + "\\ms-playwright\\chromium-1248\\chrome-win64\\chrome.exe";
const BASE = "http://localhost:3000";

async function shot(page, name, opts = {}) {
  await page.waitForTimeout(opts.wait ?? 1500);
  const file = path.join(OUT, name + ".png");
  if (opts.locator) await opts.locator.screenshot({ path: file });
  else await page.screenshot({ path: file, fullPage: !!opts.full });
  console.log("saved", name);
}

(async () => {
  const browser = await chromium.launch({ executablePath: EXE });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, colorScheme: "light" });
  const step = async (name, fn) => { try { await fn(); } catch (e) { console.log("FAILED", name, e.message.split("\n")[0]); } };

  await step("lens", async () => {
    await page.goto(BASE + "/cockpit?scenario=G60-US", { waitUntil: "networkidle" });
    await page.getByText("Got it").click().catch(() => {});
    await page.getByText("Ask a prioritization question").click();
    const box = page.locator("textarea, input[type=text]").filter({ hasNot: page.locator("[placeholder*='Title']") }).first();
    await page.getByRole("textbox").nth(0).fill("Families in the US who road-trip a lot. What should we fix first?");
    await page.getByRole("button", { name: /ask|apply|go|run/i }).first().click();
    await page.waitForTimeout(3000);
    await page.getByText("Ask a prioritization question").scrollIntoViewIfNeeded();
    await page.mouse.wheel(0, 250);
    await shot(page, "lens");
  });

  await step("weights", async () => {
    await page.goto(BASE + "/cockpit?scenario=G60-US", { waitUntil: "networkidle" });
    await page.getByText("Fine-tune weights").click();
    await page.getByText("Fine-tune weights").scrollIntoViewIfNeeded();
    await page.mouse.wheel(0, 300);
    await shot(page, "weights");
  });

  await step("challenge", async () => {
    await page.goto(BASE + "/requirements/REQ-G60-US-8ca18e?scenario=G60-US", { waitUntil: "networkidle" });
    const btn = page.getByRole("button", { name: /challenge/i }).first();
    await btn.scrollIntoViewIfNeeded();
    await btn.click();
    await page.waitForTimeout(800);
    const boxes = page.getByRole("textbox");
    const n = await boxes.count();
    for (let i = 0; i < n; i++) {
      const b = boxes.nth(i);
      if (!(await b.isVisible())) continue;
      const ph = ((await b.getAttribute("placeholder")) || "").toLowerCase();
      await b.fill(ph.includes("question") ? "Is this just a few iPhone owners, or a real pattern?" : "Want counter-evidence before I approve this.");
    }
    await page.screenshot({ path: path.join(OUT, "challenge-form.png") });
    const send = page.getByRole("button", { name: /send|submit|challenge/i }).last();
    await send.click();
    await page.waitForTimeout(3000);
    await page.getByText(/AI answer|Supporting|counter/i).first().scrollIntoViewIfNeeded().catch(() => {});
    await shot(page, "challenge");
  });

  for (const tab of ["Opportunities", "Trends", "What we do not know"]) {
    await step(tab, async () => {
      await page.goto(BASE + "/insights?scenario=G60-US", { waitUntil: "networkidle" });
      await page.getByRole("tab", { name: tab }).or(page.getByRole("button", { name: tab })).first().click();
      await shot(page, "insights-" + tab.split(" ")[0].toLowerCase(), { wait: 2500 });
    });
  }

  await step("compare", async () => {
    await page.goto(BASE + "/portfolio", { waitUntil: "networkidle" });
    await shot(page, "compare-full", { full: true });
  });

  await step("detail-evidence", async () => {
    await page.goto(BASE + "/requirements/REQ-G60-US-47878d?scenario=G60-US", { waitUntil: "networkidle" });
    await page.mouse.wheel(0, 900);
    await shot(page, "detail-scrolled");
    await page.mouse.wheel(0, 900);
    await shot(page, "detail-scrolled2");
  });

  await browser.close();
})();

