/* ReSpec slide layouts, 16:9 at 1920x1080. Import after ../tokens/tokens.css.
   Why plain CSS: opens in any browser and prints to PDF without a build step. */
@page { size: 1920px 1080px; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { background: #d9d9d9; font-family: var(--font-sans); color: var(--ink); -webkit-print-color-adjust: exact; print-color-adjust: exact; }
@media print { html, body { background: none; } .slide { margin: 0 !important; } }

/* Frame: every slide has the same top bar, three-stripe accent and footer. */
.slide { width: 1920px; height: 1080px; position: relative; overflow: hidden; background: var(--white); margin: 0 auto 40px; break-after: page; }
.slide .top { position: absolute; left: 120px; right: 120px; top: 64px; display: flex; justify-content: space-between; align-items: center; }
.slide .top img { height: 40px; }
