.stripes { position: absolute; left: 0; right: 0; top: 140px; height: 4px; display: grid; grid-template-columns: 1fr 1fr 1fr; }
.stripes i:nth-child(1) { background: var(--m-light); }
.stripes i:nth-child(2) { background: var(--m-dark); }
.stripes i:nth-child(3) { background: var(--m-red); }
.foot { position: absolute; left: 120px; right: 120px; bottom: 48px; display: flex; justify-content: space-between; font-size: 18px; color: var(--grey-500); border-top: 1px solid var(--hairline); padding-top: 16px; }
.body { position: absolute; left: 120px; right: 120px; top: 210px; bottom: 120px; }

/* Type scale */
.display { font-size: 200px; font-weight: 300; line-height: 1; }
h1 { font-size: 84px; font-weight: 300; line-height: 1.05; }
h2 { font-size: 64px; font-weight: 400; line-height: 1.1; max-width: 1500px; }
h3 { font-size: 30px; font-weight: 600; margin-bottom: 12px; }
p, li { font-size: 28px; line-height: 1.45; }
.lead { font-size: 40px; font-weight: 300; line-height: 1.35; }
.muted { color: var(--grey-500); }
.blue { color: var(--blue); }

/* Building blocks */
.tag { display: inline-block; font-size: 20px; font-weight: 600; text-transform: uppercase; color: var(--blue); border: 1.5px solid var(--blue); padding: 6px 14px; margin-bottom: 28px; }
.card { border: 1px solid var(--hairline); padding: 36px; background: var(--white); }
.card.tint { background: var(--grey-100); border-color: var(--grey-100); }
.card.accent { border-color: var(--blue); }
.card.note { border-left: 6px solid var(--role-human); }
.shot { width: 100%; border: 1px solid var(--hairline); display: block; }
.num { font-size: 120px; font-weight: 300; line-height: 1; }
.num small { font-size: 48px; }
.label { font-size: 22px; font-weight: 600; text-transform: uppercase; color: var(--grey-500); margin-top: 12px; }
.btn { display: inline-block; background: var(--blue); color: #fff; font-size: 24px; font-weight: 500; padding: 20px 36px; }
.quote { font-size: 56px; font-weight: 300; line-height: 1.25; border-left: 6px solid var(--blue); padding-left: 48px; }
.lvl { display: inline-block; width: 44px; height: 44px; color: #fff; font-weight: 600; text-align: center; line-height: 44px; font-size: 24px; margin-right: 16px; }
.role { display: inline-block; width: 22px; height: 22px; margin-right: 12px; vertical-align: -2px; }
.placeholder { background: repeating-linear-gradient(45deg, var(--grey-100), var(--grey-100) 16px, #ececec 16px, #ececec 32px); border: 1px dashed #c4c4c4; display: flex; align-items: center; justify-content: center; color: var(--grey-500); font-size: 24px; }

/* Grids */
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; }
.grid3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.grid4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.flow { display: grid; grid-template-columns: 1fr 80px 1fr 80px 1fr; align-items: center; }
.flow .arrow { font-size: 56px; color: var(--blue); text-align: center; }

/* Dark slides (title, section, closing) over a photo */
.dark { background: var(--black); color: var(--white); }
.dark .muted, .dark .foot, .dark .eyebrow { color: #a8a8a8; }
.dark .foot { border-color: #2a2a2a; }
.photo { position: absolute; inset: 0; background-size: cover; background-position: center; }
.shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(10,10,11,.92) 0%, rgba(10,10,11,.55) 50%, rgba(10,10,11,.1) 100%); }
