// Renders the first slide of a deck HTML file at 1920x1080.
const { chromium } = require("../shots/node_modules/playwright-core");
const [html, out] = process.argv.slice(2);
const EXE = process.env.LOCALAPPDATA + "\\ms-playwright\\chromium-1248\\chrome-win64\\chrome.exe";
(async () => {
  const b = await chromium.launch({ executablePath: EXE });
  const p = await b.newPage({ viewport: { width: 1920, height: 1080 } });
  await p.goto("file:///" + html.replace(/\\/g, "/"), { waitUntil: "networkidle" });
  await p.waitForTimeout(800);
  await p.locator("section.slide").first().screenshot({ path: out });
  await b.close();
  console.log("saved", out);
})();
